    "num": "52",
    "category": "C. Database & SQL (46–60)",
    "question_hi": "How to implement JWT-protected routes in Express?",
    "answer_hi": "We build an authentication middleware that inspects the `Authorization` header, strips the `Bearer ` prefix, and verifies the token using `jwt.verify()`:\n\n```javascript\nconst jwt = require('jsonwebtoken');\n\nconst authMiddleware = (req, res, next) => {\n  const authHeader = req.headers.authorization;\n  if (!authHeader || !authHeader.startsWith('Bearer ')) {\n    return res.status(401).json({ error: 'Access token required' });\n  }\n\n  const token = authHeader.split(' ')[1];\n  try {\n    const decoded = jwt.verify(token, process.env.JWT_SECRET);\n    req.user = decoded; // attach user payload\n    next();\n  } catch (err) {\n    return res.status(403).json({ error: 'Invalid or expired token' });\n  }\n};\n```",
    "question_en": "How to implement JWT-protected routes in Express?",
    "answer_en": "We build an authentication middleware that inspects the `Authorization` header, strips the `Bearer ` prefix, and verifies the token using `jwt.verify()`:\n\n```javascript\nconst jwt = require('jsonwebtoken');\n\nconst authMiddleware = (req, res, next) => {\n  const authHeader = req.headers.authorization;\n  if (!authHeader || !authHeader.startsWith('Bearer ')) {\n    return res.status(401).json({ error: 'Access token required' });\n  }\n\n  const token = authHeader.split(' ')[1];\n  try {\n    const decoded = jwt.verify(token, process.env.JWT_SECRET);\n    req.user = decoded; // attach user payload\n    next();\n  } catch (err) {\n    return res.status(403).json({ error: 'Invalid or expired token' });\n  }\n};\n```",
    "source": "written",
    "topic": "node"
